const crypto = require('crypto'), fs = require('fs'), path = require('path');
const GW = 'http://127.0.0.1:8080';
const H0 = { 'zhi-project-id': 'suzhufang' };
const pass = () => fs.readFileSync(path.join(process.env.TEMP, 'e2e_pass.txt'), 'utf8').trim();
const key = () => fs.readFileSync(path.join(__dirname, '..', '..', 'zhi2-web-admin', 'src', 'utils', 'passwordEncrypt.js'), 'utf8').match(/parse\(\s*'([^']+)'\s*\)/)[1];
function enc(pl) { const k = Buffer.from(key()), iv = Buffer.from('A-16-Byte-String'); const a = k.length == 32 ? 'aes-256-cbc' : k.length == 24 ? 'aes-192-cbc' : 'aes-128-cbc'; const c = crypto.createCipheriv(a, k, iv); return Buffer.concat([c.update(pl), c.final()]).toString('base64'); }
(async () => {
  const c = await (await fetch(GW + '/v2.0/code', { headers: H0 })).json();
  const lr = await (await fetch(GW + '/v2.0/security/auth/userLogin', { method: 'POST', headers: { 'Content-Type': 'application/json', ...H0 }, body: JSON.stringify({ username: 'zsbase', password: enc(pass()), code: c.captcha, uuid: c.uuid }) })).json();
  const d = lr.data || lr;
  const token = d.token || d.access_token || d.tokenValue || (d['Admin-Token']);
  console.log('TOPKEYS=' + JSON.stringify(Object.keys(d)));
  if (token) { require('fs').writeFileSync(path.join(process.env.TEMP, 'token6835.txt'), token); console.log('TOKEN_OK len=' + token.length); }
  else console.log('NO_TOKEN ' + JSON.stringify(d).slice(0, 600));
})().catch((e) => { console.error(e); process.exit(1); });

